/// Builds an AST expression for the operator.
fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
    use ast::Operator::*;
    match self {
        PrefixOperator::Minus => Negate(Box::new(rhs)),
        PrefixOperator::Not => Not(Box::new(rhs)),
        PrefixOperator::Plus => Identity(Box::new(rhs)),
    }
}

extras.new_content:
/// Builds an AST expression for the operator.
fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
    use ast::Operator::*;
    match self {
        PrefixOperator::Minus => ast::Expression::Operator(Negate(Box::new(rhs))),
        PrefixOperator::Not => ast::Expression::Operator(Not(Box::new(rhs))),
        PrefixOperator::Plus => ast::Expression::Operator(Identity(Box::new(rhs))),
    }
}
